edits.newText:
// Optional song-info overlay pinned to the top of the hero band (B-020), above the dot.
if (config.showSongInfo)
  Positioned(
    left: 0,
    right: 0,
    // Reserve space so long artist/title never clips or intersects
    // the centered pulsing dot, even at max dot radius.
    top: 8,
    child: Builder(
      builder: (context) {
        final heroHalfH = constraints.maxHeight / 2;
        final dotMaxRadius = min(config.maxDotSize, maxAllowed);
        // Keep the overlay fully above the dot's top edge with a small
        // visual gutter.
        final availableH = heroHalfH - dotMaxRadius - 16;
        return SizedBox(
          height: availableH.clamp(0.0, double.infinity),
          child: Opacity(
            opacity: config.textOpacity.clamp(0.0, 1.0),
            child: FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.topCenter,
              child: HeroTitleBlock(textScale: config.textScale),
            ),
          ),
        );
      },
    ),
  ),

